  "implementation": "def solve(case):
    lengths = case['lengths']
    scores = case['scores']
    budget = case['budget']
    n = len(lengths)
    dp = [None] * (budget + 1)
    dp[0] = (0.0, [])
    for i in range(n):
        L = lengths[i]
        S = scores[i]
        for cap in range(budget, L - 1, -1):
            if dp[cap - L] is not None:
                prev_score, prev_indices = dp[cap - L]
                new_score = prev_score + S
                new_indices = prev_indices + [i]
                current = dp[cap]
                if current is None:
                    dp[cap] = (new_score, new_indices)
                else:
                    cur_score, cur_indices = current
                    if new_score > cur_score:
                        dp[cap] = (new_score, new_indices)
                    elif new_score == cur_score and new_indices < cur_indices:
                        dp[cap] = (new_score, new_indices)
    best = None
    best_score = None
    best_cap = None
    best_indices = None
    for cap in range(budget + 1):
        if dp[cap] is not None:
            score, indices = dp[cap]
            if best is None:
                best = (score, cap, indices)
            else:
                if score > best[0]:
                    best = (score, cap, indices)
                elif score == best[0]:
                    if cap < best[1]:
                        best = (score, cap, indices)
                    elif cap == best[1] and indices < best[2]:
                        best = (score, cap, indices)
    best_score, best_cap, best_indices = best
    return {
        'selected_indices': best_indices,
        'tokens_used': best_cap,
        'total_score': best_score
    }"
}
